
/**
 * Warehouse Management Models
 *
 * Backend:
 * iPOS.Api
 *
 * API Route:
 * /api/branches/{branchId}/warehouses
 *
 * Warehouse IDs are internal identifiers.
 * Warehouse codes are generated by the backend.
 */

// =========================================================
// Warehouse Types
// =========================================================

export enum WarehouseType {
  General = 1,
  Main = 2,
  Sales = 3
}

// =========================================================
// Warehouse Entity / API Response
// =========================================================

export interface Warehouse {
  id: number;
  branchId: number;

  code: string;
  name: string;

  type: WarehouseType;

  isDefault: boolean;
  allowSales: boolean;
  isActive: boolean;

  /**
   * Base64-encoded SQL Server RowVersion.
   *
   * Reserved for optimistic concurrency in future
   * update and status-management operations.
   */
  rowVersion: string;
}

// =========================================================
// Create Warehouse Request
// =========================================================

export interface CreateWarehouseRequest {
  name: string;
  type: WarehouseType;

  isDefault: boolean;
  allowSales: boolean;
}

// =========================================================
// Warehouse List Query
//
// Used when the Warehouse List API is implemented.
// =========================================================

export interface WarehouseListQuery {
  code?: string;
  name?: string;

  type?: WarehouseType;
  isActive?: boolean;

  includeInactive?: boolean;

  sortBy?: string;
  sortDirection?: 'asc' | 'desc';

  pageNumber?: number;
  pageSize?: number;
}

// =========================================================
// Warehouse Paged Result
//
// Contract to be aligned with the backend List API.
// =========================================================

export interface WarehousePagedResult {
  items: Warehouse[];

  totalCount: number;
  pageNumber: number;
  pageSize: number;
  totalPages: number;

  hasPreviousPage: boolean;
  hasNextPage: boolean;
}

// =========================================================
// Update Warehouse Request
//
// Future backend operation.
// =========================================================

export interface UpdateWarehouseRequest {
  name: string;
  type: WarehouseType;
  allowSales: boolean;

  rowVersion: string;
}

// =========================================================
// Warehouse Status Change Request
//
// Future backend operation.
// =========================================================

export interface ChangeWarehouseStatusRequest {
  isActive: boolean;
  rowVersion: string;
}

// =========================================================
// Warehouse Default Change Request
//
// Future backend operation.
// =========================================================

export interface ChangeWarehouseDefaultRequest {
  rowVersion: string;
}

// =========================================================
// Warehouse Type Display
// =========================================================

export const WAREHOUSE_TYPE_OPTIONS: ReadonlyArray<{
  value: WarehouseType;
  label: string;
}> = [
  {
    value: WarehouseType.General,
    label: 'General Warehouse'
  },
  {
    value: WarehouseType.Main,
    label: 'Main Warehouse'
  },
  {
    value: WarehouseType.Sales,
    label: 'Sales Warehouse'
  }
];